  var bytes = input.bytes;
  var fPort = input.fPort;
  var data = {};
  var warnings = [];

  switch (fPort) {
    case 1:
      data.raw = bytes.map(function(b) {
        return ('0' + b.toString(16)).slice(-2);
      }).join('').toUpperCase();
      break;
    default:
      warnings.push("Unsupported fPort: " + fPort);
  }

  return {
    data: data,
    warnings: warnings
  };
